package cn.exam.sentry.core

import android.content.Context
import java.io.File

/** Only temporary files generated by this app are rotated; user-saved exports are untouched. */
object ReportCache {
    @Synchronized
    fun trim(context: Context, keep: File? = null) {
        val files = File(context.cacheDir, "reports").listFiles()?.filter { it.isFile }.orEmpty()
        val staleBefore = System.currentTimeMillis() - 24 * 60 * 60 * 1000L
        files.filter { it.name.startsWith("import-") && it.lastModified() < staleBefore }.forEach { it.delete() }
        val exports = files.filter { it.name.startsWith("sentry-") }
            .groupBy { it.nameWithoutExtension }.values
            .sortedWith(compareByDescending<List<File>> { group -> group.any { it.nameWithoutExtension == keep?.nameWithoutExtension } }
                .thenByDescending { group -> group.maxOf { it.lastModified() } })
        exports.drop(8).flatten().forEach { it.delete() }
        files.filter { it.name.startsWith("browser-card-") }
            .sortedWith(compareByDescending<File> { it == keep }.thenByDescending { it.lastModified() })
            .drop(8).forEach { it.delete() }
    }
}
